content.text:
{
  "name": "通用VISA消息式仪器",
  "name_en": "Generic VISA Message-Based Instrument",
  "manufacturer": "",
  "description": "具有串口、GPIB、USB或TCP接口，并通过消息或文本命令进行控制的通用实验室仪器。此类设备常用于实验室中的测量、控制与数据采集，典型对象包括可编程电源、万用表、示波器及各类控制器等。",
  "description_en": "A generic laboratory instrument that exposes a message- or text-based control interface over serial, GPIB, USB, or TCP. Such devices are commonly used in labs for measurement, control, and data acquisition, including programmable power supplies, multimeters, oscilloscopes, and controllers.",
  "tag_hints": [
    "VISA instrument",
    "message-based control",
    "serial communication",
    "GPIB",
    "USB instrument",
    "TCP instrument",
    "lab automation"
  ],
  "actions": [
    {
      "action_name": "auto-initialize",
      "description": "打开与仪器的通信端口。",
      "description_en": "Open the communication port to the instrument."
    },
    {
      "action_name": "auto-finalize",
      "description": "关闭与仪器的通信端口。",
      "description_en": "Close the communication port to the instrument."
    },
    {
      "action_name": "auto-is_open",
      "description": "获取通信端口是否处于打开状态。",
      "description_en": "Get whether the communication port is open."
    },
    {
      "action_name": "auto-raw_send",
      "description": "向仪器发送原始字节数据。",
      "description_en": "Send raw byte data to the instrument."
    },
    {
      "action_name": "auto-raw_recv",
      "description": "从仪器接收原始字节数据。",
      "description_en": "Receive raw byte data from the instrument."
    }
  ]
}

